+PREFIX_PACKING=${PREFIX_PACKING:-False}

 ROLLOUT_TP=${ROLLOUT_TP:-2}
 ROLLOUT_GPU_MEM_UTIL=${ROLLOUT_GPU_MEM_UTIL:-0.6}
@@ -85,6 +87,7 @@ ACTOR=(
     actor_rollout_ref.actor.entropy_coeff=${ENTROPY_COEFF}
     actor_rollout_ref.actor.fsdp_config.param_offload=False
     actor_rollout_ref.actor.fsdp_config.optimizer_offload=False
+    actor_rollout_ref.actor.fsdp_config.use_prefix_packing=${PREFIX_PACKING}
     actor_rollout_ref.actor.ppo_max_token_len_per_gpu=3000
     actor_rollout_ref.actor.use_dynamic_bsz=True
 )

@@ -34,6 +34,9 @@ fsdp_config:
   # Padding granularity, following the actor unless overridden
   pad_to_length_bucket: ${oc.select:actor_rollout_ref.actor.fsdp_config.pad_to_length_bucket,1024}

+  # Shared-prefix packing, following the actor unless overridden
+  use_prefix_packing: ${oc.select:actor_rollout_ref.actor.fsdp_config.use_prefix_packing,False}
+
 # sequence parallel size
 # same as actor_rollout_ref.actor.ulysses_sequence_parallel_size if it exists, otherwise 1
 ulysses_sequence_parallel_size: ${oc.select:actor_rollout_ref.actor.ulysses_sequence_parallel_size,1}
